// ===== CONFIGURACIÓN =====
const ZONA_HORARIA = 'America/Mexico_City';
const HORARIO = { activo: true, dias: [1, 2, 3, 4, 5], inicio: 9 * 60, fin: 18 * 60 };
const ESPERA_MINUTOS = 60; // no repetir la respuesta por defecto a la misma persona

const FUERA_DE_HORARIO = '¡Hola! 👋 Ahora mismo estoy fuera de horario (lunes a viernes de 9:00 a 18:00). Te responderé en cuanto pueda.';
const POR_DEFECTO = '¡Gracias por escribir! Este es un mensaje automático. Te responderé lo antes posible.';
const REGLAS = [
  { palabras: ['hola', 'buenas', 'buenos dias'], respuesta: '¡Hola! 👋 Gracias por tu mensaje. En breve te atiendo.' },
  { palabras: ['precio', 'costo', 'cuanto cuesta'], respuesta: 'Con gusto te comparto precios. ¿Qué producto o servicio te interesa?' },
  { palabras: ['horario', 'abren', 'cierran'], respuesta: 'Nuestro horario es de lunes a viernes de 9:00 a 18:00.' },
  { palabras: ['ubicacion', 'direccion', 'donde estan'], respuesta: 'Te comparto nuestra ubicación: (pon aquí tu dirección o enlace de Google Maps).' },
];
// =========================

const normalizar = (t) => ` ${String(t || '').toLowerCase().normalize('NFD')
  .replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9ñ\s]/g, ' ').replace(/\s+/g, ' ').trim()} `;

const ahora = new Date();
const partes = new Intl.DateTimeFormat('en-US', {
  timeZone: ZONA_HORARIA, weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
}).formatToParts(ahora);
const val = (tipo) => partes.find((p) => p.type === tipo).value;
const dia = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(val('weekday'));
const minutos = Number(val('hour')) * 60 + Number(val('minute'));
const enHorario = !HORARIO.activo
  || (HORARIO.dias.includes(dia) && minutos >= HORARIO.inicio && minutos < HORARIO.fin);

// Memoria entre ejecuciones (solo funciona con el flujo activado, no en pruebas manuales)
const memoria = $getWorkflowStaticData('global');
memoria.ultima = memoria.ultima || {};

const salida = [];
for (const item of $input.all()) {
  const datos = item.json;
  const mensaje = (datos.messages || [])[0];
  if (!mensaje) continue; // avisos de entregado/leído, no son mensajes
  const de = mensaje.from;
  const texto = normalizar(mensaje.text?.body ?? mensaje.button?.text ?? '');

  let respuesta;
  let respetaEspera = true;
  if (!enHorario) {
    respuesta = FUERA_DE_HORARIO;
  } else {
    const regla = REGLAS.find((r) => r.palabras.some((p) => texto.includes(normalizar(p))));
    if (regla) {
      respuesta = regla.respuesta;
      respetaEspera = false;
    } else {
      respuesta = POR_DEFECTO;
    }
  }

  const ultima = memoria.ultima[de];
  if (respetaEspera && ultima && ahora.getTime() - ultima < ESPERA_MINUTOS * 60 * 1000) continue;
  memoria.ultima[de] = ahora.getTime();

  salida.push({ json: { para: de, respuesta, phoneNumberId: datos.metadata?.phone_number_id } });
}
return salida;
